import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {

       System.out.println(isSubsequence("leeeeetcode",""));
    }

    public static boolean isSubsequence(String s, String t) {
        boolean isSubsequence = false;

        if (t.length() < s.length()) {
            return isSubsequence;
        }
        StringBuilder stringBuilder = new StringBuilder();
        for (int i = 0; i < t.length(); i++) {
            if (s.contains("" + t.charAt(i))) {
                stringBuilder.append(t.charAt(i));
            }
        }
        String finalComp = stringBuilder.toString();

        if (finalComp.contains(s)) {
            return true;
        }



        int lastMatch = 0;

        int position = 0;
        int sPos = 0;
        while (position < finalComp.length() && sPos<s.length()) {

            if (finalComp.charAt(position) == s.charAt(sPos) && lastMatch <= position) {
                if (sPos==s.length()-1){
                    isSubsequence = true;
                    break;
                }
                lastMatch = position;
                sPos++;
                position++;
            } else {
                position++;
            }
        }

        System.out.println("Sequence: "+ isSubsequence);
        return isSubsequence;
    }
}